<script setup lang="ts">
import { ref,computed } from 'vue'
import { useRoute } from 'vue-router'
import { get,post } from '../api/client'
import type { Model,Preparation } from '../api/types'
import { session,allowed } from '../composables/session'
import { useCursorList } from '../composables/useCursorList'
import { useQuery } from '../composables/useQuery'
import { useMutation } from '../composables/useMutation'
import { localToInstant,ratioText } from '../api/format'
import PageHeader from '../components/PageHeader.vue'
import Icon from '../components/Icon.vue'
import Feedback from '../components/Feedback.vue'
import ResourceTable from '../components/ResourceTable.vue'
import JsonView from '../components/JsonView.vue'
import Modal from '../components/Modal.vue'
const route=useRoute(),section=String(route.params.section),pid=session.project!.id,op=useMutation(),detail=ref<unknown>(null)
const title=computed(()=>({audit:'审计证据',benchmarks:'Benchmark 分层评测',evolution:'安全进化'}[section]||'安全治理'))
const audit=useCursorList<Model<'AuditEventResponse'>>(`/api/v1/projects/${pid}/audit-events`,0,section==='audit')
const benchmarks=useCursorList<Model<'BenchmarkRunResponse'>>(`/api/v1/projects/${pid}/benchmark-runs`,0,section==='benchmarks')
const datasets=useCursorList<Model<'BenchmarkDatasetResponse'>>(`/api/v1/projects/${pid}/benchmark-datasets`,0,section==='benchmarks')
const candidates=useCursorList<Model<'EvolutionCandidateResponse'>>(`/api/v1/projects/${pid}/evolution-candidates`,0,section==='evolution')
const authorizations=useCursorList<Model<'EvolutionAuthorizationResponse'>>(`/api/v1/projects/${pid}/evolution-authorizations`,0,section==='evolution')
const verification=ref<Model<'LedgerVerificationResponse'>|null>(null),dataset=ref(''),level=ref<Model<'BenchmarkLevel'>>('L0'),preparation=ref(typeof route.query.preparation==='string'?route.query.preparation:''),report=ref<unknown>(null)
const prepared=useQuery<Preparation|null>(s=>preparation.value?get(`/api/v1/preparations/${preparation.value}`,s):Promise.resolve({data:null,etag:null,requestId:''}),[preparation])
const candidate=ref<Model<'EvolutionCandidateResponse'>|null>(null),authMode=ref('shadow'),traffic=ref('0.01'),expires=ref(''),zone=ref('Asia/Shanghai')
const scopes=ref([{kind:'connection',id:'',resource:'',environment:'test',operation:'execute_etl'}])
async function verify(){const r=await op.run(()=>get<Model<'LedgerVerificationResponse'>>(`/api/v1/projects/${pid}/ledger/verification`),'');if(r)verification.value=r.data}
async function start(){await op.run(async()=>{const binding=level.value==='L2'?prepared.data.value?.preparation.evaluation_binding:null;if(level.value==='L2'&&!binding)throw new Error('L2 必须提供已批准且用途匹配的准备单');const r=await post<Model<'BenchmarkRunResponse'>>('/api/v1/benchmarks/run',{project_id:pid,dataset_id:binding?.dataset_id||dataset.value,level:level.value,provider_binding:binding?.provider_binding||{provider:'deepseek',model:import.meta.env.VITE_MODEL_NAME||'deepseek-v4.1-flash',prompt_version:'v1',policy_version:'1'},preparation_id:level.value==='L2'?preparation.value:null});report.value=r.data;await benchmarks.q.refresh();return r},'评测已受理，结果由后台生成；L0/L1 不代表真实搬运验证。')}
async function openReport(row:Record<string,unknown>){const r=await op.run(()=>get<unknown>(`/api/v1/benchmark-runs/${row.id}/report`),'');if(r)report.value=r.data}
async function openCandidate(row:Record<string,unknown>){const r=await op.run(()=>get<Model<'EvolutionCandidateResponse'>>(`/api/v1/evolution-candidates/${row.id}`),'');if(r)candidate.value=r.data}
async function authorize(){if(!candidate.value)return;if(!window.confirm('确认按当前精确资源、比例和期限授予有界授权？授权记录不等于真实流量已经切换。'))return;await op.run(()=>post('/api/v1/evolution-authorizations',{candidate_id:candidate.value!.id,mode:authMode.value,resource_scopes:scopes.value.map(s=>({connection_id:s.kind==='connection'?s.id:null,file_asset_id:s.kind==='file'?s.id:null,resource_name:s.resource,operations:[s.operation],environment:s.environment})),traffic_ratio:ratioText(traffic.value),expires_at:localToInstant(expires.value,zone.value)}),'有界授权事实已记录。');await authorizations.q.refresh()}
async function authorization(row:Record<string,unknown>){const r=await op.run(()=>get<Model<'EvolutionAuthorizationResponse'>>(`/api/v1/evolution-authorizations/${row.id}`),'');if(r)detail.value=r.data}
async function revoke(){if(!detail.value||typeof detail.value!=='object'||!('id'in detail.value)||!window.confirm('确认撤销这项有界授权？'))return;const id=String(detail.value.id);await op.run(async()=>{const current=await get<Model<'EvolutionAuthorizationResponse'>>(`/api/v1/evolution-authorizations/${id}`);return post(`/api/v1/evolution-authorizations/${id}/revoke`,undefined,{etag:current.etag})},'服务端已确认撤销。');detail.value=null;await authorizations.q.refresh()}
</script>
<template><PageHeader eyebrow="GOVERN WITH EVIDENCE" :title="title" :description="section==='audit'?'关键事件只追加，验证结果与外部锚覆盖边界分别展示。':section==='benchmarks'?'版本化样例、分层证据和可复算指标，避免将模拟误认为真实执行。':'审查候选及评测证据，只允许有界、可撤销的影子或小流量授权。'"><button v-if="section==='audit'" class="button" :disabled="op.busy.value" @click="verify"><Icon name="shield" :size="15"/>读取账本校验结果</button></PageHeader><Feedback :error="op.error.value" :notice="op.notice.value" :unknown="op.unknown.value"/>
<template v-if="section==='audit'"><section v-if="verification" class="card section-space" style="margin-bottom:20px"><div class="card-heading"><h2>链条内部一致性</h2><span class="badge" :class="verification.result==='valid'?'good':'warn'">{{verification.result}}</span></div><div class="card-body"><JsonView :value="verification"/><p v-if="!verification.checkpoint_id" class="block-note">本次没有独立检查点覆盖。链条内部一致不等于已证明历史从未截断。</p></div></section><Feedback :error="audit.q.error.value" :loading="audit.q.loading.value" @retry="audit.q.refresh()"/><section class="card"><ResourceTable :rows="audit.q.data.value?.items||[]" :columns="[{key:'event_type',label:'事件类型'},{key:'actor_kind',label:'主体类型'},{key:'sequence_no',label:'序列'},{key:'created_at',label:'记录时间',kind:'date'}]" @open="detail=$event"/><div class="pagination"><span>第 {{audit.stack.value.length}} 段</span><div><button class="button small" :disabled="audit.stack.value.length===1" @click="audit.previous">上一段</button><button class="button small" :disabled="!audit.q.data.value?.has_more" @click="audit.next">下一段</button></div></div></section></template>
<template v-else-if="section==='benchmarks'"><div class="detail-grid"><section class="card"><div class="card-heading"><h2>版本化评测记录</h2><button class="icon-button" aria-label="刷新评测记录" @click="benchmarks.q.refresh()"><Icon name="refresh" :size="16"/></button></div><Feedback :error="benchmarks.q.error.value" :loading="benchmarks.q.loading.value"/><ResourceTable :rows="benchmarks.q.data.value?.items||[]" :columns="[{key:'id',label:'评测标识',kind:'id'},{key:'level',label:'层级'},{key:'status',label:'进度',kind:'status'},{key:'created_at',label:'受理时间',kind:'date'}]" @open="openReport"/><div class="pagination"><span>第 {{benchmarks.stack.value.length}} 段</span><div><button class="button small" :disabled="benchmarks.stack.value.length===1" @click="benchmarks.previous">上一段</button><button class="button small" :disabled="!benchmarks.q.data.value?.has_more" @click="benchmarks.next">下一段</button></div></div></section><section class="card"><div class="card-heading"><h2>发起分层评测</h2></div><form class="card-body form-stack" @submit.prevent="start"><label class="field">既有用例集<select v-model="dataset" name="dataset" :required="level!=='L2'"><option value="">选择版本化数据集</option><option v-for="d in datasets.q.data.value?.items||[]" :key="d.id" :value="d.id">{{d.name}} · {{d.version}}</option></select></label><Feedback :error="datasets.q.error.value"/><label class="field">评测层级<select v-model="level" name="level"><option value="L0">L0 · 静态门禁</option><option value="L1">L1 · 确定性故障模拟</option><option value="L2">L2 · 真实受管执行</option></select></label><label v-if="level==='L2'" class="field">已审批的 L2 准备单 UUID<input v-model.lazy="preparation" name="preparation" required/><small>用例集与模型绑定使用准备单的冻结事实</small></label><Feedback :error="prepared.error.value"/><div v-if="level==='L2'" class="block-note">先在冻结版本页申请 L2 用途并完成双槽审批，再回到此处启动。不会使用正式执行的 Commit 入口。</div><p class="form-info">DeepSeek · {{prepared.data.value?.preparation.evaluation_binding?.provider_binding.model||'deepseek-v4.1-flash'}}<br>没有可判定样本时指标为未知，不显示100%通过。</p><button class="button primary" :disabled="!allowed('run_benchmark')||op.busy.value||op.unknown.value">发起评测</button></form></section></div><section v-if="report" class="card section-space"><div class="card-heading"><h2>实际观察与指标</h2></div><div class="card-body"><JsonView :value="report"/></div></section></template>
<template v-else><div class="block-note">安全候选需要服务端证据和基线校验。当前真实候选生成与流量路由仍未接入，不提供全量上线按钮。</div><Feedback :error="candidates.q.error.value||authorizations.q.error.value"/><section class="card"><div class="card-heading"><h2>待审查候选</h2></div><ResourceTable :rows="candidates.q.data.value?.items||[]" :columns="[{key:'candidate_version',label:'候选版本'},{key:'kind',label:'类型'},{key:'base_version',label:'基线版本'},{key:'created_at',label:'创建时间',kind:'date'}]" @open="openCandidate"/><div class="pagination"><span>第 {{candidates.stack.value.length}} 段</span><div><button class="button small" :disabled="candidates.stack.value.length===1" @click="candidates.previous">上一段</button><button class="button small" :disabled="!candidates.q.data.value?.has_more" @click="candidates.next">下一段</button></div></div></section><section class="card section-space"><div class="card-heading"><h2>有界授权记录</h2></div><ResourceTable :rows="authorizations.q.data.value?.items||[]" :columns="[{key:'mode',label:'方式'},{key:'traffic_ratio',label:'比例（0—1）'},{key:'status',label:'状态',kind:'status'},{key:'expires_at',label:'截止时间',kind:'date'}]" @open="authorization"/><div class="pagination"><span>第 {{authorizations.stack.value.length}} 段</span><div><button class="button small" :disabled="authorizations.stack.value.length===1" @click="authorizations.previous">上一段</button><button class="button small" :disabled="!authorizations.q.data.value?.has_more" @click="authorizations.next">下一段</button></div></div></section></template>
<Modal :open="detail!==null" title="安全事实详情" @close="detail=null"><JsonView :value="detail"/><div v-if="section==='evolution'" class="form-actions"><button class="button danger" :disabled="!allowed('revoke_evolution')||op.busy.value||op.unknown.value" @click="revoke">申请撤销这项授权</button></div></Modal>
<Modal :open="candidate!==null" title="审查安全进化候选" :busy="op.busy.value" @close="candidate=null"><template v-if="candidate"><JsonView :value="candidate"/><p class="block-note">由服务端核对安全证据、基线效果、允许范围与期限。不会由前端评分决定晋级。</p><form class="form-stack" @submit.prevent="authorize"><label class="field">有界模式<select v-model="authMode" name="authMode"><option value="shadow">影子模式</option><option value="canary">小流量模式</option></select></label><fieldset v-for="(s,i) in scopes" :key="i" style="border:1px solid var(--border);border-radius:8px;padding:16px"><legend>精确资源 {{i+1}}</legend><div class="form-grid"><label class="field">资源类型<select v-model="s.kind"><option value="connection">连接</option><option value="file">文件</option></select></label><label class="field">已有资源 UUID<input v-model="s.id" required/></label><label class="field">资源名称<input v-model="s.resource" required/></label><label class="field">环境<input v-model="s.environment" required/></label><label class="field full">工具操作<select v-model="s.operation"><option v-for="tool in ['execute_etl','run_l2_benchmark','publish','cancel','pause','resume','rollback','cleanup','profile']" :key="tool">{{tool}}</option></select></label></div></fieldset><button type="button" class="button" @click="scopes.push({kind:'connection',id:'',resource:'',environment:'test',operation:'execute_etl'})">添加精确资源</button><label class="field">流量比例（0—1 的精确文本）<input v-model="traffic" name="traffic" required inputmode="decimal"/></label><label class="field">到期时刻所属时区<input v-model="zone" name="zone" required/></label><label class="field">到期本地时刻<input v-model="expires" name="expires" type="datetime-local" required/></label><Feedback :error="op.error.value" :notice="op.notice.value"/><button class="button primary" :disabled="!allowed('authorize_evolution')||!allowed('approve_security')||op.busy.value||op.unknown.value">确认有界授权</button></form></template></Modal></template>
